import os as _os
_ROOT = _os.path.normpath(_os.path.join(_os.path.dirname(_os.path.abspath(__file__)), '..', '..', '..'))   # THE PORTABLE REPO (2026-09-15): the repo root from this file's own place
#!/usr/bin/env python3
# THE DEUTERONOMY WALK sitting 17 — CHAPTERS 22-25 (LEAN, 2026-09-26; THE TAIL): the store's glosses at the four chapters' seats read back into the display layer's
# override file — BY GLOSS where the store's every token of the gloss is the one word or one family read the same at every seat (the families PROBED FIRST by
# ch22_patch_probe.py, the counts read from its print; the glosses the earlier walks already rewrote by gloss excluded — the probe's own list), BY REFERENCE at the
# chapters' own seats where the family is mixed (and where an earlier sitting's by-gloss row reads wrong at a new seat — 24:6's millstone under "and-chariot").
# THE LEAN FORM: the worst glosses only; the rest OWED. Display only; the frozen units untouched. Run ONCE (the anchors assert the rows absent first).
# Sitting 16's form (ch19_patch_overrides.py): the anchors the LAST ROWS of sitting 16's two blocks — the by_gloss block's last row found by walking from sitting 16's
# marker (never typed), the by_ref block's last row 21:23's. The seat helpers (sg, sidx) read the store here — the sitting's ink carries none. RUN FROM THE REPO ROOT; after the freeze chain.
import re, sqlite3, subprocess, yaml
ROOT = _ROOT
store = sqlite3.connect(f'file:{ROOT}/torah_grok.SNAPSHOT-main-51801ca.sqlite?mode=ro', uri=True)
SG = {}
for c, v, i, hp, g in store.execute("SELECT v.chapter, v.verse, w.idx, w.he_plain, w.gloss FROM words w JOIN verses v ON w.verse_id=v.id WHERE v.book='Deut' AND v.chapter IN (22, 23, 24, 25) ORDER BY v.id, w.idx"):
    SG.setdefault((c, v), []).append((i, hp.replace('/', ''), g))
def sg(c, v, tok, nth=0):
    hit = [g for _, hp, g in SG[(c, v)] if hp == tok]; assert len(hit) > nth, (c, v, tok, nth, hit); return hit[nth]
def sidx(c, v, tok, nth=0):
    hit = [i for i, hp, _ in SG[(c, v)] if hp == tok]; assert len(hit) > nth, (c, v, tok, nth, hit); return hit[nth]
