REF3 = [(f'Deut.{c}.{v}:{sidx(c, v, tok, nth)}', new, tok) for c, v, tok, new, nth in SPEC]
REF = [(k, v) for k, v, _ in REF3]; TOK = {k: t for k, _, t in REF3}
assert len(REF) == len({k for k, _ in REF}) == len(SPEC) and len(GL) == len({g for g, _ in GL})
assert all(sg(c, v, tok, nth) != new for c, v, tok, new, nth in SPEC), [(c, v, tok) for c, v, tok, new, nth in SPEC if sg(c, v, tok, nth) == new]   # no row rewrites a gloss to itself
assert all(sg(c, v, tok, nth) not in dict(GL) for c, v, tok, _, nth in SPEC), [(c, v, tok, sg(c, v, tok, nth)) for c, v, tok, _, nth in SPEC if sg(c, v, tok, nth) in dict(GL)]   # a seat patched by gloss is not patched again by reference
P = f'{ROOT}/logic/glosses/word_gloss_overrides.yaml'
t = open(P, encoding='utf-8').read()
d0 = yaml.safe_load(t); BG0 = d0['by_gloss']
assert not re.search(r'"Deut\.2[2-5]\.', t) and all(g not in BG0 for g, _ in GL), [g for g, _ in GL if g in BG0]
MARK = 'THE DEUTERONOMY WALK sitting 17 (2026-09-26, Deuteronomy 22-25, LEAN)'
assert MARK not in t
M16 = 'THE DEUTERONOMY WALK sitting 16 (2026-09-24, Deuteronomy 19-21, LEAN)'
i = t.index(f'  # {M16}: the worst glosses of the three chapters\' seats')
j = t.index('\n', i) + 1
rows = []
while True:
    m = re.match(r'  "[^"]+": "[^"]*"[^\n]*\n', t[j:])
    if not m: break
    rows.append(m.group(0)); j += len(m.group(0))
assert len(rows) == 89, len(rows)   # sitting 16's by-gloss rows (its patch print "by_gloss 89"; the probe's walk 89)
A1 = rows[-1]; assert t.count(A1) == 1
gl_block = A1 + f'\n  # {MARK}: the worst glosses of the four chapters\' seats, the families probed in the store first (ch22_patch_probe.py) — the lean form\'s patch; the rest OWED (COMPILE_DEBT\'s lean-pass box)\n' + ''.join(f'  "{k}": "{v}"\n' for k, v in GL)
t = t.replace(A1, gl_block)
m2 = re.search(r'^  "Deut\.21\.23:13": "a-hanged-one"[^\n]*\n', t, re.M); assert m2 and t.count('"Deut.21.23:13": "a-hanged-one"') == 1
A2 = m2.group(0)
ref_block = A2 + f'  # {MARK}: the four chapters\' seats by reference — the token named beside each; the indices the store\'s own (24:6\'s millstone under an earlier by-gloss row read here by reference)\n' + ''.join(f'  "{k}": "{v}"   # {TOK[k]}\n' for k, v in REF)
t = t.replace(A2, ref_block)
open(P, 'w', encoding='utf-8').write(t)
d = yaml.safe_load(open(P, encoding='utf-8'))
assert all(d['by_ref'][k] == v for k, v in REF) and all(d['by_gloss'][k] == v for k, v in GL)
print('override rows written: by_ref', len(REF), 'by_gloss', len(GL), '| by_ref total', len(d['by_ref']), '| by_gloss total', len(d['by_gloss']))
